struct PacketHeader {
    uint8_t version;
    uint8_t flags;
    uint16_t packet_id;
};

PacketHeader read_packet_header(const std::span<const uint8_t> buffer) {
    // Use subspan() to create a zero-copy view of the header portion
    auto header_span = buffer.subspan(0, sizeof(PacketHeader));

    // Reinterpret the bytes as PacketHeader structure (zero-copy)
    const auto* header = reinterpret_cast<const PacketHeader*>(header_span.data());
    return *header;
