    // Find the null terminator position
    const auto* data = buffer.data();
    const auto* null_pos = static_cast<const uint8_t*>(
        std::memchr(data, 0, buffer.size())
    );

    if (!null_pos) {
        // Handle case where no null terminator is found
        return std::string_view();
    }

    // Create a zero-copy string_view up to the delimiter
    size_t length = null_pos - data;
    return std::string_view(reinterpret_cast<const char*>(data), length);
}
