			}

			head = head->next;
		}

		return npos;
	}

	/**
	 * @brief Retrieves the container's allocator.
	 * 
	 * @return The memory allocator.
	 */
	auto& get_allocator() {
		return allocator_;
	}

	/**
	 * @brief Retrieves the container's allocator.
	 * 
	 * @return The memory allocator.
	 */
	auto& get_allocator() const {
		return allocator_;
	}

	template<typename buffer_type>
	friend class buffer_sequence;
