```cpp
std::vector<uint8_t> read_partial_data(const std::vector<uint8_t>& buffer, std::size_t chunk_size) {
    hexi::pmc::buffer_read_adaptor<const std::vector<uint8_t>> reader(buffer);
    std::vector<uint8_t> result;
    result.reserve(buffer.size());

    // Read until buffer is empty
    while (!reader.empty()) {
        // Determine how much to read
        std::size_t to_read = std::min(chunk_size, reader.size());

        // Prepare space for reading
        std::size_t old_size = result.size();
        result.resize(old_size + to_read);

        // Read partial data
        reader.read(result.data() + old_size, to_read);

        // Check remaining data after each read
        std::size_t remaining = reader.size();
    }

    return result;
}
```

This approach is more efficient - I'm pre-allocating the full buffer size and writing directly into the result vector rather than creating temporary vectors and inserting them.

